+    {
+        READWRITE(Using<BigEndianFormatter<BLOCK_SEQ_SIZE>>(obj.block_seq),
+                  Using<BigEndianFormatter<TX_OFFSET_SIZE>>(obj.tx_offset_in_block));
+    }
+};
